function demoMain(idx,label){
  var cache={};var keys=[["user:1","Alice"],["order:9","#9001"],["cfg:theme","dark"]];
  var k=keys[idx%keys.length];var hits=0,miss=0;
  function get(key){if(cache[key]){hits++;return cache[key];}miss++;cache[key]="val-"+key;return cache[key];}
  get(k[0]);get(k[0]);get("other");
  return "["+label+"] set "+k[0]+"='"+k[1]+"' -> hits="+hits+" misses="+miss+" hit-rate="+(hits/(hits+miss)*100).toFixed(0)+"%";
}

